/* VERITAS Health Intelligence — Styles & Design Tokens */

:root {
  --bg-dark: #060D19;
  --bg-card: #0A1628;
  --bg-card-alt: #0F2040;
  --bg-card-subtle: #091324;
  --bg-red-alert: #1A0E18;

  --border-color: #1A2F4C;
  --border-card: #1B355A;
  --border-teal: #00C9B1;
  --border-red: #E74C3C;
  --border-amber: #F5A623;

  --text-primary: #FFFFFF;
  --text-secondary: #E8F4FD;
  --text-muted: #7A9BC2;
  --text-dim: #54739E;

  --accent-teal: #00C9B1;
  --accent-blue: #3A86FF;
  --accent-amber: #F5A623;
  --accent-red: #E74C3C;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-dark);
  color: var(--text-secondary);
  line-height: 1.5;
  font-size: 14px;
}

/* App Layout */
.app-layout {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* Header */
.veritas-header {
  height: 56px;
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.5rem;
}

.brand-group {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}

.brand-logo {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: 1px;
  color: var(--text-primary);
}

.brand-sub {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--accent-teal);
  letter-spacing: 1px;
}

.header-breadcrumbs {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.crumb-pill {
  color: var(--text-muted);
}

.crumb-pill.active {
  color: var(--accent-teal);
  font-weight: 600;
}

.crumb-separator {
  color: var(--text-dim);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.search-box {
  position: relative;
  display: flex;
  align-items: center;
}

.search-box input {
  background-color: var(--bg-card-subtle);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 0.4rem 2rem 0.4rem 0.8rem;
  color: var(--text-primary);
  font-size: 0.8rem;
  width: 220px;
}

.search-box kbd {
  position: absolute;
  right: 8px;
  background: #142845;
  border: 1px solid #234578;
  color: var(--text-muted);
  font-size: 0.7rem;
  padding: 1px 4px;
  border-radius: 4px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.45rem 1rem;
  border-radius: 6px;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.2s ease;
}

.btn-primary {
  background-color: var(--accent-teal);
  color: var(--bg-dark);
}
.btn-primary:hover { background-color: #00B39E; }

.btn-secondary {
  background-color: var(--bg-card-alt);
  color: var(--text-primary);
  border-color: var(--border-card);
}
.btn-secondary:hover { background-color: #162B50; }

.btn-outline {
  background-color: transparent;
  color: var(--text-secondary);
  border-color: var(--border-card);
}
.btn-outline:hover { background-color: var(--bg-card-alt); border-color: var(--border-teal); }

.btn-danger {
  background-color: var(--accent-red);
  color: #FFFFFF;
}
.btn-danger:hover { background-color: #C0392B; }

.btn-sm {
  padding: 0.25rem 0.6rem;
  font-size: 0.75rem;
}

.btn-block {
  width: 100%;
}

.badge-ready {
  background: rgba(0, 201, 177, 0.2);
  color: var(--accent-teal);
  font-size: 0.68rem;
  padding: 2px 6px;
  border-radius: 4px;
  margin-left: 6px;
}

/* Main Body */
.main-body {
  display: flex;
  flex: 1;
}

/* Sidebar Rail */
.sidebar-rail {
  width: 240px;
  background-color: var(--bg-card);
  border-right: 1px solid var(--border-color);
  padding: 1.2rem 1rem;
  display: flex;
  flex-direction: column;
}

.nav-section-title {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text-dim);
  letter-spacing: 1px;
  margin-bottom: 0.8rem;
}

.nav-menu {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  flex: 1;
}

.nav-item {
  display: flex;
  align-items: center;
  padding: 0.6rem 0.8rem;
  color: var(--text-muted);
  text-decoration: none;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  transition: background 0.15s, color 0.15s;
}

.nav-item:hover {
  background-color: var(--bg-card-alt);
  color: var(--text-primary);
}

.nav-item.active {
  background-color: var(--bg-card-alt);
  color: var(--accent-teal);
  border-left: 3px solid var(--accent-teal);
  font-weight: 600;
}

.auditor-profile-card {
  background: var(--bg-card-subtle);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 0.8rem;
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.profile-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #142845;
  color: var(--accent-teal);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.85rem;
}

.profile-name { font-weight: 700; color: var(--text-primary); font-size: 0.85rem; }
.profile-role { font-size: 0.75rem; color: var(--accent-teal); }
.profile-sync { font-size: 0.7rem; color: var(--text-dim); margin-top: 2px; }
.pulse-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-teal);
  margin-right: 4px;
}

/* Content Workspace */
.content-workspace {
  flex: 1;
  padding: 1.2rem 1.8rem;
  overflow-y: auto;
}

/* Toolbar */
.facility-toolbar {
  display: flex;
  align-items: center;
  gap: 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 0.8rem 1.2rem;
  margin-bottom: 1.2rem;
}

.toolbar-label {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

.facility-dropdown {
  flex: 1;
  background-color: var(--bg-dark);
  border: 1px solid var(--border-card);
  color: var(--text-primary);
  padding: 0.4rem 0.8rem;
  border-radius: 6px;
